css:
.letter-head {
  text-align: center;
  margin-bottom: 12px;
}
.letter-head img {
  max-height: 60px;
}
.proposal-cover {
  border-top: 4px solid #724b68;
  padding-top: 18px;
  margin: 8px 0 28px;
}
.draft-badge {
  display: inline-block;
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: #9c3349;
  background: #fbe9ec;
  border: 1px solid #f0c3cd;
  border-radius: 3px;
  padding: 2px 8px;
  margin-bottom: 8px;
}
.proposal-cover h1 {
  font-size: 24px;
  margin: 0 0 6px;
  color: #241c22;
}
.proposal-meta {
  color: #6b6478;
  font-size: 11px;
}
.proposal-section {
  margin-bottom: 22px;
}
.proposal-section h3 {
  border-left: 3px solid #724b68;
  padding-left: 10px;
  margin-bottom: 8px;
  font-size: 14px;
  letter-spacing: 0.01em;
  color: #241c22;
}
.section-no {
  color: #724b68;
  font-weight: 700;
  margin-right: 6px;
}
.section-body {
  font-size: 12.5px;
  line-height: 1.6;
}
.letter-head-footer {
  font-size: 9.5px;
  color: #6b6478;
  text-align: center;
  border-top: 1px solid #e4ddef;
  padding-top: 6px;
}

html:
{% set template = frappe.get_doc("Proposal Template", doc.proposal_template) %}
{% set client_account = frappe.db.get_value("Bid", doc.bid, "client_account") %}
{% set ns = namespace(section_no=0) %}
{% macro render_section(key, default_label, content) %}
  {% set matches = template.sections | selectattr("section_key", "equalto", key) | list %}
  {% set row = matches[0] if matches else none %}
  {% if row and row.is_included and content %}
    {% set ns.section_no = ns.section_no + 1 %}
    <div class="proposal-section">
      <h3><span class="section-no">{{ ns.section_no }}.</span>{{ row.section_label or default_label }}</h3>
      <div class="section-body">{{ content }}</div>
    </div>
  {% endif %}
{% endmacro %}

<div {% if print_settings.repeat_header_footer %}id="header-html" class="hidden-pdf"{% endif %}>
  {% if letter_head and not no_letterhead %}
  <div class="letter-head">{{ letter_head }}</div>
  {% endif %}
</div>

<div class="proposal-cover">
  {% if doc.status == "Draft" %}<div class="draft-badge">DRAFT</div>{% endif %}
  <h1>{{ doc.title or ("Proposal — " ~ (client_account or doc.bid)) }}</h1>
  <div class="proposal-meta">{{ client_account or doc.bid }} &middot; Version {{ doc.version }}</div>
</div>

{{ render_section("executive_summary", "Executive Summary", doc.executive_summary) }}
{{ render_section("technical_approach", "Technical Approach", doc.technical_approach) }}
{{ render_section("commercial_terms", "Commercial Terms", doc.commercial_terms) }}
{{ render_section("compliance_statement", "Compliance Statement", doc.compliance_statement) }}

<div {% if print_settings.repeat_header_footer %}id="footer-html" class="visible-pdf"{% endif %}>
  {% if footer and not no_letterhead %}
  <div class="letter-head-footer">{{ footer }}</div>
  {% endif %}
</div>
